const st = {};
$('Get Drafting Settings').all().forEach(function (it) { if (it.json && it.json.key) st[it.json.key] = String(it.json.value == null ? '' : it.json.value); });
const scope = st.draftScope === 'inbox' ? 'inbox' : 'senders';
const max = Math.min(50, Math.max(1, parseInt(st.maxEmails || '25', 10) || 25));
const BASE = '-in:sent -in:draft -in:chats -from:me';
// 'Your addresses' filter from the Mailroom app (empty = every address is tracked).
const ADDR = st.addressQuery ? ' ' + st.addressQuery : '';
if (scope === 'inbox') {
  return [{ json: { scope: scope, maxEmails: max, gmailQuery: 'in:inbox ' + BASE +
    ' -category:promotions -category:social -category:updates -category:forums' +
    ' -from:noreply -from:no-reply -from:donotreply -from:do-not-reply -from:mailer-daemon -from:notifications -from:newsletter' + ADDR } }];
}
const pats = [];
$('Get Tracked Senders').all().forEach(function (it) {
  const j = it.json || {};
  if (!j.matchPatterns || j.active === false || String(j.active) === 'false') return;
  String(j.matchPatterns).split(',').forEach(function (p) {
    p = p.trim().replace(/"/g, '');
    if (p && pats.indexOf(p) < 0) pats.push(p);
  });
});
if (!pats.length) return [];
return [{ json: { scope: scope, maxEmails: max,
  gmailQuery: '{' + pats.map(function (p) { return 'from:"' + p + '"'; }).join(' ') + '} ' + BASE + ADDR } }];

const emails = $('Filter Already-Drafted').all();
let rows = [];
try { rows = $('Check Pending Proposal').all().map(function (it) { return it.json; }); } catch (e) { rows = []; }
let senders = [];
try { senders = $('Get Tracked Senders').all().map(function (it) { return it.json; }).filter(function (s) { return s && s.matchPatterns; }); } catch (e) { senders = []; }
const st = {};
try { $('Get Drafting Settings').all().forEach(function (it) { if (it.json && it.json.key) st[it.json.key] = String(it.json.value == null ? '' : it.json.value); }); } catch (e) { /* defaults */ }
const signer = st.signatureName || 'Alex Doe';
function senderFor(email) {
  const from = String((email.from && email.from.text) || '').toLowerCase();
  for (let k = 0; k < senders.length; k++) {
    const pats = String(senders[k].matchPatterns || '').split(',').map(function (p) { return p.trim().toLowerCase(); }).filter(Boolean);
    if (pats.some(function (p) { return from.indexOf(p) >= 0; })) return senders[k];
  }
  return null;
}
function stamp(r) { return String(r.processedAt || r.createdAt || ''); }
return emails.map(function (it, i) {
  const email = it.json;
  const pending = rows.filter(function (r) { return r.threadId && r.threadId === email.threadId && r.proposalStatus === 'pending'; })
    .sort(function (a, b) { return stamp(b).localeCompare(stamp(a)); });
  let slots = [];
  if (pending.length) { try { slots = JSON.parse(pending[0].proposedSlotsJson || '[]') || []; } catch (e) { slots = []; } }
  const hasPending = slots.length > 0;
  const s = senderFor(email);
  return { json: Object.assign({}, email, {
    hasPendingProposal: hasPending,
    pendingSlotsText: slots.map(function (x) { return x && x.label; }).filter(Boolean).join('; '),
    pendingSlotsParsed: slots,
    proposalStatus: hasPending ? 'pending' : '',
    senderName: signer,
    senderNotes: (s && s.notes) || st.defaultNotes || '',
    contactName: (s && s.senderName) || '',
    draftScope: st.draftScope === 'inbox' ? 'inbox' : 'senders',
    senderCategory: (s && s.category) || st.defaultCategory || 'career',
    senderCalendarId: (s && s.calendarId) || ''
  }), pairedItem: { item: 0 } };
});

