const classifyItems = $input.all();
let emailItems = [];
try {
  emailItems = $("Attach Pending Proposal Context").all();
} catch (e) {
  emailItems = [];
}
const results = [];
for (let i = 0; i < classifyItems.length; i++) {
  const classifyJson = classifyItems[i].json;
  const emailJson = (emailItems[i] && emailItems[i].json) ? emailItems[i].json : {};
  const merged = Object.assign({}, emailJson, {
    output: classifyJson.output
  });
  results.push({ json: merged, pairedItem: { item: i } });
}
return results;

const confirmedIndex = ($json.output && typeof $json.output.confirmedSlotIndex === "number") ? $json.output.confirmedSlotIndex : -1;
const slots = $json.pendingSlotsParsed || [];
const chosen = (confirmedIndex >= 0 && confirmedIndex < slots.length) ? slots[confirmedIndex] : null;
const startISO = chosen ? chosen.startISO : "";
const endISO = chosen ? chosen.endISO : "";
const label = chosen ? chosen.label : "";
return { json: Object.assign({}, $json, { startISO: startISO, endISO: endISO, label: label }) };

function selfDeclined(e) { return (e.attendees || []).some(function (a) { return a.self && a.responseStatus === 'declined'; }); }
function busyInterval(e) {
  if (!e || !e.start || e.status === 'cancelled' || selfDeclined(e)) return null;
  if (e.eventType === 'workingLocation' || e.eventType === 'birthday') return null;
  if (e.start.dateTime) {
    if (e.transparency === 'transparent') return null;
    return { s: DateTime.fromISO(e.start.dateTime), e: DateTime.fromISO(e.end.dateTime), allDay: false };
  }
  if (e.start.date) return { s: DateTime.fromISO(e.start.date, { zone: 'Europe/Rome' }).startOf('day'), e: DateTime.fromISO(e.end.date, { zone: 'Europe/Rome' }).startOf('day'), allDay: true };
  return null;
}
function parseJ(s, f) { try { const v = JSON.parse(s); return v == null ? f : v; } catch (e) { return f; } }

function readSettings(node) {
  const st = {};
  try { $(node).all().forEach(function (it) { if (it.json && it.json.key) st[it.json.key] = String(it.json.value == null ? '' : it.json.value); }); } catch (e) { /* defaults */ }
  return st;
}

function readBusy(node) {
  const res = { events: [], ok: true, failed: [], checked: [] };
  let items = [];
  try { items = $(node).all(); } catch (e) { res.ok = false; res.failed.push('busy calendars not read'); return res; }
  if (!items.length) { res.ok = false; res.failed.push('busy calendars returned nothing'); }
  items.forEach(function (it) {
    const e = it.json || {};
    if (e.__summary) { res.checked = e.calendars || []; return; }
    if (e.__calendarError) { res.ok = false; res.failed.push(e.calendarName || e.calendarId); return; }
    if (e.error) { res.ok = false; res.failed.push(String((e.error && e.error.message) || e.error)); return; }
    if (e.start) res.events.push(e);
  });
  return res;
}

const ZONE = 'Europe/Rome';
const now = DateTime.now().setZone(ZONE);
const reqs = $('Is Appointment Request?').all(0);
const st = readSettings('Get Drafting Settings');
const HOURS = {
  fulltime: parseJ(st.workHours, {}),
  career: parseJ(st.careerHours, {}),
  anytime: parseJ(st.anytimeHours, {})
};
const LABEL = { fulltime: 'full-time job', career: 'professional career', anytime: 'any time' };

// 1. Busy time from every busy calendar (+ each sender's own calendar).
//    Long events in the work calendar are presence blocks ("at work"): they block every
//    category except full-time-job senders, whose meetings are placed inside them.
const WORK_CAL = st.workCalendar || '';
const PRESENCE_MIN = (Number(st.presenceMinHours) || 4) * 60;
const cal = readBusy('Get Busy Events');
const calendarOk = cal.ok;
const busy = [];
const presence = [];
cal.events.forEach(function (e) {
  const b = busyInterval(e);
  if (!b) return;
  const isPresence = WORK_CAL && e.__calendarId === WORK_CAL && !b.allDay && b.e.diff(b.s, 'minutes').minutes >= PRESENCE_MIN;
  if (isPresence) presence.push({ s: b.s, e: b.e });
  busy.push({ s: b.s, e: b.e, thread: '', presence: !!isPresence });
});

// 2. Slots already offered to other people in the last 7 days and not yet answered are held.
let rows = [];
try { rows = $('Check Pending Proposal').all().map(function (it) { return it.json; }); } catch (e) { rows = []; }
function when(v) {
  if (v instanceof Date) return DateTime.fromJSDate(v);
  const d = DateTime.fromISO(String(v || ''));
  return d.isValid ? d : null;
}
rows.forEach(function (r) {
  if (r.proposalStatus !== 'pending') return;
  const t = when(r.processedAt || r.createdAt);
  if (t && t < now.minus({ days: 7 })) return;
  let slots = [];
  try { slots = JSON.parse(r.proposedSlotsJson || '[]') || []; } catch (e) { slots = []; }
  slots.forEach(function (x) {
    const s = DateTime.fromISO(String((x && x.startISO) || '')), e = DateTime.fromISO(String((x && x.endISO) || ''));
    if (s.isValid && e.isValid) busy.push({ s: s, e: e, thread: r.threadId || '' });
  });
});

// 3. Allowed windows per category, in minutes from midnight.
function mins(hhmm) { const p = String(hhmm).split(':'); return (Number(p[0]) || 0) * 60 + (Number(p[1]) || 0); }
function ranges(table, wd) { return ((table || {})[String(wd)] || []).map(function (r) { return [mins(r[0]), mins(r[1])]; }).filter(function (r) { return r[1] > r[0]; }); }
function subtract(rs, cuts) {
  cuts.forEach(function (w) {
    const next = [];
    rs.forEach(function (r) {
      if (w[1] <= r[0] || w[0] >= r[1]) { next.push(r); return; }
      if (w[0] > r[0]) next.push([r[0], w[0]]);
      if (w[1] < r[1]) next.push([w[1], r[1]]);
    });
    rs = next;
  });
  return rs;
}
function clip(rs, a, b) { return rs.map(function (r) { return [Math.max(r[0], a), Math.min(r[1], b)]; }).filter(function (r) { return r[1] > r[0]; }); }
function presenceRanges(day) {
  // Presence blocks that day, never earlier than the day's first fixed work hour (commute).
  const fixed = ranges(HOURS.fulltime, day.weekday);
  const floor = fixed.length ? Math.min.apply(null, fixed.map(function (r) { return r[0]; })) : 7 * 60 + 30;
  const d0 = day.startOf('day');
  return presence.filter(function (p) { return p.s < d0.plus({ days: 1 }) && p.e > d0; }).map(function (p) {
    const a = Math.max(0, Math.round(p.s.setZone(ZONE).diff(d0, 'minutes').minutes));
    const b = Math.min(24 * 60, Math.round(p.e.setZone(ZONE).diff(d0, 'minutes').minutes));
    return [Math.max(a, floor), b];
  }).filter(function (r) { return r[1] > r[0]; });
}
function windowsFor(category, day, part) {
  let rs;
  if (category === 'fulltime') {
    rs = presenceRanges(day);                                     // real shifts when the calendar has them
    if (!rs.length) rs = ranges(HOURS.fulltime, day.weekday);     // otherwise the fixed work hours
  } else {
    rs = ranges(HOURS[category] || HOURS.career, day.weekday);
  }
  if (category === 'career') rs = subtract(rs, ranges(HOURS.fulltime, day.weekday));   // never during work hours
  if (part === 'morning') rs = clip(rs, 0, 13 * 60);
  if (part === 'afternoon') rs = clip(rs, 13 * 60, 24 * 60);
  return rs.sort(function (a, b) { return a[0] - b[0]; });
}
function isFree(s, e, thread, category) {
  return !busy.some(function (b) {
    if (b.presence && category === 'fulltime') return false;
    return (!b.thread || b.thread !== thread) && s < b.e && e > b.s;
  });
}
function earliest() {
  let t = now.plus({ hours: 2 });
  t = t.minute === 0 ? t.startOf('hour') : (t.minute <= 30 ? t.set({ minute: 30, second: 0, millisecond: 0 }) : t.plus({ hours: 1 }).startOf('hour'));
  return t;
}
function search(from, to, category, part, dur, thread, max, perDay) {
  // perDay = 1 spreads the offer over different days; alternate days start mid-window
  // so that not every proposal is at the start of the window.
  const out = [];
  let day = from.startOf('day');
  let k = 0;
  while (day <= to && out.length < max) {
    const rs = windowsFor(category, day, part);
    let starts = [];
    rs.forEach(function (r) { for (let m = r[0]; m + dur <= r[1]; m += 30) starts.push([m, r[1]]); });
    if (k % 2 === 1 && starts.length > 2) {
      const mid = Math.floor(starts.length / 2);
      starts = starts.slice(mid).concat(starts.slice(0, mid));
    }
    const today = [];
    for (let q = 0; q < starts.length && today.length < perDay && out.length + today.length < max; q++) {
      const s = day.plus({ minutes: starts[q][0] });
      const e = s.plus({ minutes: dur });
      const spaced = today.every(function (x) { return s >= x.e.plus({ minutes: 60 }) || e <= x.s.minus({ minutes: 60 }); });
      if (s >= from && e <= to.endOf('day') && spaced && isFree(s, e, thread, category)) today.push({ s: s, e: e });
    }
    if (today.length) { today.sort(function (a, b) { return a.s - b.s; }); Array.prototype.push.apply(out, today); k++; }
    day = day.plus({ days: 1 });
  }
  return out;
}

const results = reqs.map(function (it) {
  const base = it.json || {};
  const o = base.output || {};
  const category = HOURS[base.senderCategory] ? base.senderCategory : (HOURS[st.defaultCategory] ? st.defaultCategory : 'career');
  let dur = Number(o.durationMinutes) || 30;
  dur = Math.min(180, Math.max(15, Math.ceil(dur / 15) * 15));
  const part = ['morning', 'afternoon'].indexOf(o.preferredPartOfDay) >= 0 ? o.preferredPartOfDay : 'any';
  const min = earliest();
  const ps = DateTime.fromISO(String(o.preferredStartDate || ''), { zone: ZONE });
  const pe = DateTime.fromISO(String(o.preferredEndDate || ''), { zone: ZONE });
  let from = ps.isValid && ps.startOf('day') > min ? ps.startOf('day') : min;
  if (from > now.plus({ days: 60 })) from = min;
  let to = pe.isValid && pe >= from.startOf('day') ? pe.endOf('day') : from.plus({ days: 14 }).endOf('day');
  if (to > now.plus({ days: 75 })) to = now.plus({ days: 75 }).endOf('day');
  const hinted = ps.isValid || pe.isValid || part !== 'any';

  let found = [];
  let relaxed = false;
  // Widen step by step, always keeping what was already found inside the request.
  function merge(more) {
    more.forEach(function (f) {
      if (found.length >= 3) return;
      const clash = found.some(function (x) { return f.s < x.e.plus({ minutes: 60 }) && f.e > x.s.minus({ minutes: 60 }); });
      if (!clash) found.push(f);
    });
    found.sort(function (a, b) { return a.s - b.s; });
  }
  if (calendarOk) {
    found = search(from, to, category, part, dur, base.threadId, 3, 1);
    if (found.length < 2) merge(search(from, to, category, part, dur, base.threadId, 3, 3));
    if (found.length < 2 && part !== 'any') merge(search(from, to, category, 'any', dur, base.threadId, 3, 3));
    if (found.length < 2) merge(search(min, min.plus({ days: 14 }).endOf('day'), category, 'any', dur, base.threadId, 3, 1));
  }
  // Flag only when at least one offered time is actually outside what was asked.
  relaxed = hinted && found.some(function (f) {
    const h = f.s.setZone(ZONE).hour;
    return f.s < from || f.e > to.endOf('day') || (part === 'morning' && h >= 13) || (part === 'afternoon' && h < 13);
  });
  found.forEach(function (f) { busy.push({ s: f.s, e: f.e, thread: '' }); }); // never offer the same slot twice in one run
  const freeSlots = found.map(function (f) {
    return { startISO: f.s.toISO(), endISO: f.e.toISO(), label: f.s.toFormat('cccc d LLLL, HH:mm') + '-' + f.e.toFormat('HH:mm') };
  });
  let text;
  if (!calendarOk) text = '(Calendar temporarily unavailable -- could not confirm free slots right now.)';
  else if (!freeSlots.length) text = 'No free slots found in the next two weeks.';
  else text = freeSlots.map(function (s) { return s.label; }).join('; ');
  return { json: Object.assign({}, base, { freeSlots: freeSlots, freeSlotsText: text, slotsRelaxed: relaxed,
    meetingMinutes: dur, calendarOk: calendarOk, schedulingCategory: category, schedulingCategoryLabel: LABEL[category],
    calendarsChecked: cal.checked, calendarsFailed: cal.failed }), pairedItem: { item: 0 } };
});
return results;

