let classifyOutput = {};
let orig = {};
if ($json && $json.output) {
  classifyOutput = $json.output;
  orig = $json;
} else {
  try {
    orig = $('Compute Free Slots').item.json;
    classifyOutput = orig.output || { isAppointmentRequest: true, isConfirmingProposal: false };
  } catch (e) {
    try {
      orig = $('Extract Confirmed Slot').item.json;
      classifyOutput = orig.output || { isAppointmentRequest: false, isConfirmingProposal: true };
    } catch (e2) {
      orig = {};
      classifyOutput = {};
    }
  }
}
const isAppt = classifyOutput.isAppointmentRequest === true;
const isConfirming = classifyOutput.isConfirmingProposal === true;

let apptLlmText = '';
try {
  const apptItem = $('Draft Appointment Reply').item;
  apptLlmText = (apptItem && typeof apptItem.json.text === 'string') ? apptItem.json.text.trim() : '';
} catch (e) {
  apptLlmText = '';
}
const replyText = apptLlmText.length ? apptLlmText : ((classifyOutput.draftReply || '').trim());
const rawSubject = orig.subject || '(no subject)';
const draftSubject = /^re:/i.test(rawSubject) ? rawSubject : ('Re: ' + rawSubject);
const fromObj = orig.from || {};
const fromValues = fromObj.value || [];
const sendTo = (fromValues[0] && fromValues[0].address) || fromObj.text || '';
const finalBody = replyText.length ? replyText : '(No reply generated)';

const skipDraft = !isAppt && !isConfirming && classifyOutput.needsReply === false;
let proposalStatus = skipDraft ? 'no_reply_needed' : 'none';
let proposedSlotsJson = '';
if (isConfirming) {
  // The booking itself waits for Alex's BOOK / DO NOT BOOK choice (Gmail Assistant - Decisions).
  proposalStatus = orig.startISO ? 'awaiting_approval' : 'none';
} else if (isAppt && (orig.freeSlots || []).length) {
  proposalStatus = 'pending';
  proposedSlotsJson = JSON.stringify(orig.freeSlots);
}
return { json: { draftSubject: draftSubject, draftBody: finalBody, threadId: orig.threadId, sendTo: sendTo, originalMessageId: orig.id,
  isAppointmentRequest: isAppt, proposalStatus: proposalStatus, proposedSlotsJson: proposedSlotsJson, meetingEventId: '',
  skipDraft: skipDraft } };

function parseJ(s, f) { try { const v = JSON.parse(s); return v == null ? f : v; } catch (e) { return f; } }

function readSettings(node) {
  const st = {};
  try { $(node).all().forEach(function (it) { if (it.json && it.json.key) st[it.json.key] = String(it.json.value == null ? '' : it.json.value); }); } catch (e) { /* defaults */ }
  return st;
}

const ZONE = 'Europe/Rome';
const URL = 'https://YOUR-N8N-HOST/webhook/mailroom-decide-CHANGE-ME';
const st = readSettings('Get Drafting Settings');
const names = {};
