// Draft follow-up (port of logic.draft_check + handled_ids). One item out: {changes, handled, ok, counts}.
function stg(k, d) { const r = $('Get Drafting Settings').all().find(function (i) { return i.json && i.json.key === k; }); const v = parseInt(r && r.json.value, 10); return v > 0 ? v : d; }
const DAY = 86400000, FOLLOW_DAYS = stg('followUpDays', 7);
const REPLY = ['none', 'pending', 'awaiting_approval', 'withdrawn'];
const REDRAFTABLE = ['none', 'pending', 'withdrawn'];
const FINAL = ['sent', 'discarded', 'superseded'];
const DEAD = ['deleted', 'discarded', 'superseded'];
function ms(v) {
  if (v == null || v === '') return 0;
  if (v instanceof Date) return v.getTime();
  if (typeof v === 'number') return v;
  const s = String(v);
  if (/^\d+(\.\d+)?$/.test(s)) return Math.floor(Number(s));
  const d = DateTime.fromISO(s, { zone: 'Europe/Rome' });
  return d.isValid ? d.toMillis() : 0;
}
function items(node) { try { return $(node).all().map(function (i) { return i.json || {}; }); } catch (e) { return null; } }
const rows = (items('Get Processed (Follow-up)') || []).filter(function (r) { return r && r.id != null && r.trackedGmailId; });
const draftsRaw = items('Get Drafts');
const sentRaw = items('Get Sent (8 days)');
// Never mark drafts as deleted when Gmail could not be read.
const ok = draftsRaw !== null && sentRaw !== null &&
  !draftsRaw.some(function (d) { return d.error; }) && !sentRaw.some(function (m) { return m.error; });
const drafts = (draftsRaw || []).filter(function (d) { return d.threadId; });
const sent = (sentRaw || []).filter(function (m) { return m.threadId; });
const now = DateTime.now().toMillis();
const since = now - FOLLOW_DAYS * DAY;
const draftThreads = {};
drafts.forEach(function (d) { if (String(d.subject || '').indexOf('[Inbox Pilot]') !== 0) draftThreads[d.threadId] = true; });
const sentAt = {};
sent.forEach(function (m) { (sentAt[m.threadId] = sentAt[m.threadId] || []).push(ms(m.internalDate)); });
const reply = rows.filter(function (r) { return r.threadId && REPLY.indexOf(r.proposalStatus) >= 0; });
const latest = {};
reply.forEach(function (r) {
  const k = [ms(r.processedAt), Number(r.id) || 0];
  const cur = latest[r.threadId];
  if (!cur || k[0] > cur.k[0] || (k[0] === cur.k[0] && k[1] > cur.k[1])) latest[r.threadId] = { k: k, id: r.id };
});
const changes = [];
if (ok) {
  reply.forEach(function (r) {
    const cur = String(r.draftStatus || '');
    const at = ms(r.processedAt);
    if (FINAL.indexOf(cur) >= 0 || at < since) return;
    let next;
    if ((sentAt[r.threadId] || []).some(function (t) { return t >= at; })) next = 'sent';
    else if (latest[r.threadId].id !== r.id) next = 'superseded';
    else if (draftThreads[r.threadId]) next = 'ready';
    else next = 'deleted';
    if (next !== cur) {
      const c = { id: r.id, draftStatus: next };
      if (DEAD.indexOf(next) >= 0 && r.proposalStatus === 'pending') c.proposalStatus = 'withdrawn';
      changes.push(c);
    }
  });
}
const byId = {};
rows.forEach(function (r) { byId[r.id] = r; });
changes.forEach(function (c) { if (byId[c.id]) Object.assign(byId[c.id], c); });
// Emails not to draft again: all processed ones, except a reply whose draft was deleted unsent.
const newest = {};
rows.forEach(function (r) {
  const g = String(r.trackedGmailId);
  if (!newest[g] || (Number(r.id) || 0) > (Number(newest[g].id) || 0)) newest[g] = r;
});
const handled = Object.keys(newest).filter(function (g) {
  const r = newest[g];
  return !(r.draftStatus === 'deleted' && REDRAFTABLE.indexOf(r.proposalStatus) >= 0);
});
return [{ json: { ok: ok, changes: changes, handled: handled } }];

// One item per row to update; proposalStatus is always written (unchanged unless the proposal was withdrawn).
