// ---- CORE START
function stg(k, d) { const r = $('Get Drafting Settings').all().find(function (i) { return i.json && i.json.key === k; }); const v = parseInt(r && r.json.value, 10); return v > 0 ? v : d; }
const REF_DAYS = stg('earlierItemsDays', 60), REF_TOP = 6;
const DOC_HOSTS = ['docs.google.com', 'drive.google.com', 'dropbox.com', '1drv.ms', 'onedrive.live.com',
  'sharepoint.com', 'wetransfer.com', 'we.tl', 'box.com', 'icloud.com', 'notion.so', 'figma.com'];
const URL_RE = /https?:\/\/[^\s"'<>)\]]+/g;
const DOC_EXT = /\.(pdf|docx?|xlsx?|pptx?|odt|ods|odp|csv|zip|rar|7z|key|pages|numbers|rtf|txt)(?:[?#]|$)/i;
const INLINE = /^(image\d*|inline|outlook-|logo|signature)/i;
const NOT_DOC = ['text/calendar', 'application/ics', 'application/pkcs7-signature', 'application/x-pkcs7-signature'];
const SCHEMA_TAIL = '\n\nReturn a JSON object with exactly these keys and value types, as in this example:\n' +
  JSON.stringify({ matchIndex: 0, draftReply: 'Hi Anna,\n\nyes, your file arrived on 3 October.\n\n[your comments]\n\nBest,\nAlex' })
    .replace(/,"/g, ', "').replace(/":/g, '": ');

function refQuery(addr) {
  return 'from:"' + addr + '" {has:attachment "docs.google.com" "drive.google.com" "dropbox.com" "1drv.ms" ' +
    '"sharepoint.com" "onedrive" "wetransfer" "we.tl"} -in:chats -in:draft';
}
function refTokens(s) {
  const out = new Set();
  (String(s || '').toLowerCase().match(/[\p{L}\p{N}]{3,}/gu) || []).forEach(function (t) { out.add(t); });
  return out;
}
function refDay(ms) { return ms ? DateTime.fromMillis(ms, { zone: 'Europe/Rome' }).toISODate() : ''; }
function refInt(v) { const n = parseInt(v, 10); return isNaN(n) ? 0 : n; }

function referenceCandidates(msgs, current, keywords) {
  const curMs = refInt(current.internalDate);
  const kws = refTokens((keywords || []).map(String).join(' '));
  const found = [];
  msgs.forEach(function (m) {
    if (m.id === current.id) return;
    const ms = refInt(m.internalDate);
    if (curMs && ms > curMs) return;
    const subject = String(m.subject || '');
    const same = !!current.threadId && m.threadId === current.threadId;
    const base = { messageId: m.id || '', threadId: m.threadId || '', subject: subject, at: refDay(ms), ms: ms,
      sameThread: same, unread: (m.labelIds || []).indexOf('UNREAD') >= 0 };
    (m.attachments || []).forEach(function (a) {
      const fn = String(a.filename || '').trim();
      const mime = String(a.mimeType || '').toLowerCase();
      const low = fn.toLowerCase();
      if (!fn || NOT_DOC.indexOf(mime) >= 0 || low.endsWith('.ics') || low.endsWith('.p7s')) return;
      if (mime.startsWith('image/') && INLINE.test(fn)) return;
      found.push(Object.assign({}, base, { kind: 'attachment', name: fn, url: '' }));
    });
    const seen = new Set();
    ((String(m.text || '') + ' ' + String(m.html || '')).match(URL_RE) || []).forEach(function (raw) {
      const u = raw.replace(/&amp;/g, '&').replace(/[.,;:]+$/, '');
      const low = u.toLowerCase();
      if (seen.has(low) || !(DOC_HOSTS.some(function (h) { return low.indexOf(h) >= 0; }) || DOC_EXT.test(low))) return;
      seen.add(low);
      found.push(Object.assign({}, base, { kind: 'link', name: u.slice(0, 160), url: u }));
    });
  });
  found.forEach(function (c) {
    let hit = 0;
    refTokens(c.name + ' ' + c.subject).forEach(function (t) { if (kws.has(t)) hit += 1; });
    c.score = 3 * hit + (c.sameThread ? 2 : 0);
  });
  found.sort(function (a, b) {
    if (a.score !== b.score) return b.score - a.score;
    if (a.ms !== b.ms) return b.ms - a.ms;
    if (a.kind !== b.kind) return a.kind < b.kind ? -1 : 1;
    const x = a.name.toLowerCase(), y = b.name.toLowerCase();
    return x < y ? -1 : (x > y ? 1 : 0);
  });
  const out = [], keys = new Set();
  for (const c of found) {
    const k = c.kind + '\u0000' + c.name.toLowerCase();
    if (keys.has(k)) continue;
    keys.add(k);
    out.push(c);
    if (out.length === REF_TOP) break;
  }
  return out;
}

function referenceLines(cands) {
  if (!cands.length) return '(none found)';
  return cands.map(function (c, i) {
    return i + '. ' + (c.kind === 'attachment' ? 'Attachment' : 'Link') + ': ' + c.name + ' | received ' + c.at +
      ' | email subject: "' + (c.subject || '(no subject)') + '"' + (c.sameThread ? ' | same conversation' : '');
  }).join('\n');
}

function refBody(j) {
  let t = String(j.text || '').trim();
  if (!t) {
    t = String(j.html || '').replace(/<style[\s\S]*?<\/style>/gi, ' ');
    t = t.replace(/<[^>]+>/g, ' ');
  }
  t = t.replace(/[ \t]+/g, ' ');
  return t.replace(/\n{3,}/g, '\n\n').trim().slice(0, 8000);
}

function referencePrompt(j, cands, now) {
  const signer = j.senderName || 'Alex Doe';
  const desc = ((j.output || {}).referenceDescription) || '(not specified)';
  const d = now.setZone('Europe/Rome').setLocale('en');
  const today = d.toFormat('cccc') + ' ' + d.day + ' ' + d.toFormat('LLLL yyyy');
  const frm = (j.from && j.from.text) || 'unknown';
  const block = '<email>\nFrom: ' + frm + '\nSubject: ' + (j.subject || '(no subject)') + '\nBody:\n' +
    (refBody(j) || '(no body available)') + '\n</email>';
  return 'Today is ' + today + ' (Europe/Rome).\n\n' +
    'You are drafting an email reply on behalf of ' + signer + ', who received the email below. The sender refers to something sent earlier: ' + desc + '.\n\n' +
    'Instructions for this sender: ' + (j.senderNotes || '(none)') + '\n\n' +
    'Original email:\n' + block + '\n\n' +
    'Items found in the recipient\'s mailbox from this sender in the last ' + REF_DAYS + ' days (attachments and document links, best matches first):\n' +
    referenceLines(cands) + '\n\n' +
    'STEP 1 -- MATCH: set matchIndex to the number of the item that is what the sender refers to. If none of the items clearly matches, set matchIndex to -1. Do not pick an unrelated item.\n\n' +
    'STEP 2 -- DRAFT: write a complete, natural, ready-to-edit reply in draftReply.\n' +
    '- If matchIndex is not -1: confirm that the item arrived, naming it and the date it was received. Never say or imply that it has been read, reviewed, approved or forwarded. Put the placeholder [your comments] on its own line where the recipient will add his own view, then close politely.\n' +
    '- If matchIndex is -1: say politely that you cannot find it in your inbox and ask the sender to send it again or to share the link.\n' +
    '- Answer any other question in the email only with facts stated above; where a fact is unknown, use a placeholder in square brackets.\n' +
    'Reply in the same language the original email was written in. Follow the sender-specific instructions above if any are given. Sign off as ' + String(signer).split(' ')[0] + '.\n\n' +
    'Respond with ONLY the JSON object matching the required schema. No explanation, no markdown code fences, no text before or after the JSON.' + SCHEMA_TAIL;
}
// ---- CORE END

// For every email that refers to something sent earlier: the Gmail results paired to it, ranked.
const emails = $('Refers To Earlier?').all(0);
const results = $input.all();
function pairOf(r) {
  const p = Array.isArray(r.pairedItem) ? r.pairedItem[0] : r.pairedItem;
  return p && typeof p.item === 'number' ? p.item : -1;
}
return emails.map(function (e, i) {
  const mine = results.filter(function (r) { return pairOf(r) === i; });
  const failed = mine.some(function (r) { return r.json && r.json.error; });
  const msgs = mine.filter(function (r) { return r.json && r.json.id; }).map(function (r) {
