  const kws = (((ej.output || {}).referenceKeywords) || []).map(String).filter(function (k) { return k.trim(); }).slice(0, 5);
  const cands = failed ? [] : referenceCandidates(msgs, current, kws);
  const firstIdx = results.indexOf(mine[0]);
  return { json: Object.assign({}, ej, { refCandidates: cands, refLookupFailed: failed,
    refPrompt: failed ? '' : referencePrompt(ej, cands, $now) }), pairedItem: { item: firstIdx >= 0 ? firstIdx : 0 } };
